import numpy as np
from autograd import Tensor


def sig(t):
    return 1.0 / (1.0 + (-t).exp())


def copy_batch(T, n, rng, noise=0.2):
    s = rng.choice([-1.0, 1.0], size=n)
    X = noise * rng.standard_normal((T, n))
    X[0] = s
    F = np.zeros((T, n))
    F[0] = 1.0
    return X, F, (s > 0).astype(float)


def init_gated(seed):
    g = np.random.default_rng(seed)
    p = {k: Tensor(0.5 * g.standard_normal()) for k in ['w', 'ux', 'uf', 'b', 'ax', 'af', 'ah', 'c', 'v', 'd']}
    p['w'] = Tensor(0.9)
    p['c'] = Tensor(-3.0)
    return p


def gated_step(h, x, f, p):
    z = sig(p['ax'] * x + p['af'] * f + p['ah'] * h + p['c'])
    cand = (p['w'] * h + p['ux'] * x + p['uf'] * f + p['b']).tanh()
    return (1.0 - z) * h + z * cand


def bce(logit, y):
    m = logit * (2 * y - 1)
    return ((-m).exp() + 1.0).log().mean()


def accuracy(p, T):
    X, F, y = copy_batch(T, 1000, np.random.default_rng(99))
    h = Tensor(np.zeros(1000))
    for t in range(T):
        h = gated_step(h, X[t], F[t], p)
    return float((((p['v'] * h + p['d']).data > 0) == (y > 0.5)).mean())

